    -- Adiciona as extensões cube e earthdistance para indices e cálculos de distância
    CREATE EXTENSION IF NOT EXISTS cube;
    CREATE EXTENSION IF NOT EXISTS earthdistance;

    --Adiciona location a city
    ALTER TABLE city
        ADD COLUMN location_cube cube
            GENERATED ALWAYS AS (ll_to_earth(latitude, longitude)::cube) STORED;

    --Adiciona location a state
    ALTER TABLE state
        ADD COLUMN location_cube cube
            GENERATED ALWAYS AS (ll_to_earth(latitude, longitude)::cube) STORED;

    -- Index espacial para city
    CREATE INDEX idx_city_location_cube ON city
        USING gist (location_cube);

    -- Index espacial para state
    CREATE INDEX idx_state_location_cube ON state
        USING gist (location_cube);

    -- Função para cálculo de distância entre uma origem e as cidades da tabela city.
    CREATE OR REPLACE FUNCTION f_city_distance_km(origin cube)
        RETURNS TABLE (
                          city_id int,
                          distance_km double precision
                      )
        LANGUAGE sql
    AS $$
    SELECT
        c.city_id,
        earth_distance(origin, c.location_cube) / 1000 AS distance_km
    FROM city c
    ORDER BY distance_km;
    $$;

    ALTER FUNCTION public.f_city_distance_km
        OWNER TO "quero_doar";

    -- Função para cálculo de distância entre uma origem e os estados da tabela state.
    CREATE OR REPLACE FUNCTION f_state_distance_km(origin cube)
        RETURNS TABLE (
                          state_id int,
                          distance_km double precision
                      )
        LANGUAGE sql
    AS $$
    SELECT
        s.state_id,
        earth_distance(origin, s.location_cube) / 1000 AS distance_km
    FROM state s
    ORDER BY distance_km;
    $$;

    ALTER FUNCTION public.f_state_distance_km
        OWNER TO "quero_doar";

    -- View que expõe os dados estáticos para DonationPreview,
    -- expoõe city_id para calculo pela f_donation_preview_final.
    create or replace view public.v_donation_preview
    as
    select donation.donation_id
         ,city.city_id
         ,donation.title
         ,donation.description
         ,donation.photos[1] as photo
         ,(case when donation.type = 'D' then true else false end) as is_donation
         ,donation.is_public
         ,city.name || ' (' || state.acronym || ')' as location
         ,donation_log.date
         ,json_build_object(
            'user_id', "user".user_id,
            'name', "user".name,
            'photo', "user".photo
          ) as user_minimal
    from donation
             inner join address on donation.address_id = address.address_id
             inner join city on address.city_id = city.city_id
             inner join state on city.state_id = state.state_id
             inner join donation_log on donation.donation_id = donation_log.donation_id
        and donation_log.log_type_id = (select log_type_id from log_type where  identifier = 'CREATE')
             inner join "user" on donation.creator_user_id = "user".user_id;

    ALTER VIEW public.v_donation_preview
        OWNER TO "quero_doar";

    -- Função que retorna valores finais para um DonationPreview, recebe como parâmetro
    -- o nome de uma cidade brasileira para o cálculo da distância.
    CREATE OR REPLACE FUNCTION f_donation_preview_final(city_name text)
        RETURNS TABLE (
                          donation_id int,
                          title text,
                          description text,
                          photo text,
                          is_donation boolean,
                          is_public boolean,
                          location text,
                          date timestamp,
                          user_minimal json,
                          distance_km double precision
                      )
        LANGUAGE sql
    AS $$
    WITH origin AS (
        SELECT c.location_cube
        FROM city c
        WHERE c.name = city_name
        LIMIT 1
    ),
         distance AS (
             SELECT d.city_id, d.distance_km
             FROM origin o,
                  f_city_distance_km(o.location_cube) d
         )
    SELECT
        v.donation_id,
        v.title,
        v.description,
        v.photo,
        v.is_donation,
        v.is_public,
        v.location,
        v.date,
        v.user_minimal,
        dist.distance_km
    FROM v_donation_preview v
             JOIN distance dist ON v.city_id = dist.city_id
    $$;

    ALTER FUNCTION public.f_donation_preview_final
        OWNER TO "quero_doar";

END;